// Each step is priced against the state the steps before it established, so
// the walk is sequential: thread the state through, collecting one result per
// step. The results array mirrors the input steps in length and order.
export const runScenario = (scenario: Scenario): ScenarioResult => {
  let state: ScenarioState = {
    customer: scenario.customer,
    contractsSoFar: 0,
    policies: new Map(),
  };
  const results: Result[] = [];
  scenario.steps.forEach((step, stepIndex) => {
    const outcome = runStep(step, state, stepIndex);
    results.push(outcome.result);
    state = outcome.state;
  });
  return { results };
};

